#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>

__device__ __forceinline__ float swiglu_f(float av, float bv) {
    return (av * (1.0f / (1.0f + __expf(-av)))) * bv;
}

__global__ void swiglu_float_contig(const float* __restrict__ a, const float* __restrict__ b, float* __restrict__ c, long long total) {
    long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (; i < total; i += stride) c[i] = swiglu_f(a[i], b[i]);
}

__global__ void swiglu_half2_contig(const __half2* __restrict__ a, const __half2* __restrict__ b, __half2* __restrict__ c, long long n2) {
    long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (; i < n2; i += stride) {
        __half2 ah = a[i], bh = b[i];
        float2 af = __half22float2(ah), bf = __half22float2(bh);
        c[i] = __floats2half2_rn(swiglu_f(af.x, bf.x), swiglu_f(af.y, bf.y));
    }
}

__global__ void swiglu_half_contig(const __half* __restrict__ a, const __half* __restrict__ b, __half* __restrict__ c, long long total) {
    long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (; i < total; i += stride) c[i] = __float2half_rn(swiglu_f(__half2float(a[i]), __half2float(b[i])));
}

__global__ void swiglu_bf162_contig(const __nv_bfloat162* __restrict__ a, const __nv_bfloat162* __restrict__ b, __nv_bfloat162* __restrict__ c, long long n2) {
    long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (; i < n2; i += stride) {
        __nv_bfloat162 ah = a[i], bh = b[i];
