__global__ void swiglu_float_strided(const float* __restrict__ a, const float* __restrict__ b, float* __restrict__ c,
                                     long long N, long long D, long long sa, long long sb, long long sc) {
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x, total = N * D;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        long long row = idx / D, col = idx - row * D;
        c[row * sc + col] = swiglu_f(a[row * sa + col], b[row * sb + col]);
