static inline int grid_for(long long n, int threads) {
    long long blocks = (n + threads - 1) / threads;
    if (blocks < 1) blocks = 1;
    if (blocks > 4096) blocks = 4096;
    return (int)blocks;
}

torch::Tensor swiglu_cuda(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "inputs must be CUDA");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "inputs must be 2D");
    TORCH_CHECK(a.sizes() == b.sizes(), "input sizes must match");
    TORCH_CHECK(a.scalar_type() == b.scalar_type(), "dtypes must match");
    auto c = torch::empty_like(a);
    long long N = a.size(0), D = a.size(1), total = N * D;
    if (total == 0) return c;
    constexpr int threads = 256;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    bool contig = a.is_contiguous() && b.is_contiguous() && c.is_contiguous();
    auto dtype = a.scalar_type();
    if (contig) {
        if (dtype == at::kFloat) {
            swiglu_float_contig<<<grid_for(total, threads), threads, 0, stream>>>(a.data_ptr<float>(), b.data_ptr<float>(), c.data_ptr<float>(), total);
        } else if (dtype == at::kHalf) {
            const __half* ap = reinterpret_cast<const __half*>(a.data_ptr<at::Half>());
            const __half* bp = reinterpret_cast<const __half*>(b.data_ptr<at::Half>());
            __half* cp = reinterpret_cast<__half*>(c.data_ptr<at::Half>());
            if ((total & 1LL) == 0) {
                long long n2 = total >> 1;
                swiglu_half2_contig<<<grid_for(n2, threads), threads, 0, stream>>>(reinterpret_cast<const __half2*>(ap), reinterpret_cast<const __half2*>(bp), reinterpret_cast<__half2*>(cp), n2);
            } else swiglu_half_contig<<<grid_for(total, threads), threads, 0, stream>>>(ap, bp, cp, total);
        } else if (dtype == at::kBFloat16) {
            const __nv_bfloat16* ap = reinterpret_cast<const __nv_bfloat16*>(a.data_ptr<at::BFloat16>());
            const __nv_bfloat16* bp = reinterpret_cast<const __nv_bfloat16*>(b.data_ptr<at::BFloat16>());
            __nv_bfloat16* cp = reinterpret_cast<__nv_bfloat16*>(c.data_ptr<at::BFloat16>());
            if ((total & 1LL) == 0) {
                long long n2 = total >> 1;
                swiglu_bf162_contig<<<grid_for(n2, threads), threads, 0, stream>>>(reinterpret_cast<const __nv_bfloat162*>(ap), reinterpret_cast<const __nv_bfloat162*>(bp), reinterpret_cast<__nv_bfloat162*>(cp), n2);
            } else swiglu_bf16_contig<<<grid_for(total, threads), threads, 0, stream>>>(ap, bp, cp, total);
        } else TORCH_CHECK(false, "unsupported dtype");
    } else {
        long long sa = a.stride(0), sb = b.stride(0), sc = c.stride(0);
        int blocks = grid_for(total, threads);
        if (dtype == at::kFloat) swiglu_float_strided<<<blocks, threads, 0, stream>>>(a.data_ptr<float>(), b.data_ptr<float>(), c.data_ptr<float>(), N, D, sa, sb, sc);
        else if (dtype == at::kHalf) swiglu_half_strided<<<blocks, threads, 0, stream>>>(reinterpret_cast<const __half*>(a.data_ptr<at::Half>()), reinterpret_cast<const __half*>(b.data_ptr<at::Half>()), reinterpret_cast<__half*>(c.data_ptr<at::Half>()), N, D, sa, sb, sc);
        else if (dtype == at::kBFloat16) swiglu_bf16_strided<<<blocks, threads, 0, stream>>>(reinterpret_cast<const __nv_bfloat16*>(a.data_ptr<at::BFloat16>()), reinterpret_cast<const __nv_bfloat16*>(b.data_ptr<at::BFloat16>()), reinterpret_cast<__nv_bfloat16*>(c.data_ptr<at::BFloat16>()), N, D, sa, sb, sc);
        else TORCH_CHECK(false, "unsupported dtype");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return c;
}
